@RestController
@RequestMapping("/api/users")
public class UserController {

    @PostMapping
    public ResponseEntity<User> createUser(@RequestBody UserDto dto) {
        User saved = userService.create(dto);
        return ResponseEntity.status(HttpStatus.CREATED).body(saved);
    }

    @PutMapping("/{id}")
    public ResponseEntity<User> fullUpdateUser(@PathVariable Long id, @RequestBody UserDto dto) {
        User updated = userService.upsert(id, dto);
        return ResponseEntity.ok(updated);
    }

    @PatchMapping("/{id}")
    public ResponseEntity<User> partialUpdateUser(@PathVariable Long id, @RequestBody Map<String, Object> updates) {
        User updated = userService.patch(id, updates);
        return ResponseEntity.ok(updated);
    }
}
